function shell(body){let nav=user.role==='Client'?[['home','Dashboard']]:[['home','Dashboard'],['tools','Tools']];return `<section class="workspace"><header class="app-header">${logo()}<nav class="top-nav">${nav.map(x=>`<button class="nav ${route===x[0]?'active':''}" data-route="${x[0]}">${x[1]}</button>`).join('')}</nav><div class="header-actions"><span class="header-divider"></span><div class="profile"><div><strong>Welcome, ${e(user.name.split(' ')[0])}</strong><br><small>${user.role}</small></div><span class="avatar">${user.name[0]}</span></div><button class="ghost" data-action="logout">Sign out</button></div></header><main class="content">${body}</main><footer class="app-footer"><strong>VAAK</strong><span>© 2026 VAAK Procurement Solutions. All rights reserved.</span></footer></section>`}
function card(x){return `<article class="project-card project-card-clickable" data-project="${x.id}" tabindex="0"><img class="project-cover" src="${x.cover||assets[x.id]||''}" alt="${e(x.name)} project image"><div class="project-main"><p class="eyebrow">${x.code}</p><h3>${e(x.name)}</h3><p class="muted">Project management, procurement coordination, and delivery follow-up.</p><div class="meta"><span>Installation start<strong>${x.installation}</strong></span><span>Opening<strong>${x.opening}</strong></span></div></div></article>`}
