function details(){let x=p(),orders=data.orders.filter(o=>o.projectId===x.id),gallery=x.gallery||[],banner=x.cover||assets[x.id]||'';let rows=orders.map(o=>`<article class="data-row"><div><strong>${e(o.number)}</strong><p>${e(o.supplier||o.manufacturer||'')} · Issued by ${e(o.issuer||'')} · ${e(o.date||o.issueDate||'')}</p></div><div class="order-actions"><button class="order-icon" title="Preview Purchase Order" data-action="preview-order" data-id="${o.id}">◉</button><button class="order-icon" title="Print or save PDF" data-action="download-order" data-id="${o.id}">⇩</button>${user.role!=='Client'?`<button class="order-icon delete-order" title="Delete Purchase Order" data-action="delete-order" data-id="${o.id}">⌫</button>`:''}${status('Issued')}</div></article>`).join('')||'<div class="empty">No purchase orders for this project yet.</div>';return shell(`<img class="project-banner" src="${banner}" alt="${e(x.name)} project banner"><button class="back-link" data-route="home">← Back to dashboard</button><section class="hero project-hero"><div><p class="eyebrow">${x.code} · PROJECT DETAIL</p><h1>${e(x.name)}</h1></div></section><section class="details"><article class="card"><h3>General information</h3><dl><div><dt>Legal business name</dt><dd>${e(x.legal)}</dd></div><div><dt>Tax ID</dt><dd>${e(x.tax)}</dd></div><div><dt>Fiscal address</dt><dd>${e(x.fiscal)}</dd></div><div><dt>Delivery / warehouse</dt><dd>${e(x.warehouse)}</dd></div></dl></article><article class="card"><h3>Project areas</h3><dl><div><dt>Guest rooms</dt><dd>${e(x.rooms)}</dd></div><div><dt>Residences</dt><dd>${e(x.residences)}</dd></div><div><dt>Common areas</dt><dd>${e(x.areas)}</dd></div></dl></article><article class="card"><h3>Client team</h3><p>Project Client Contact<br>Project coordination<br>contact@example.test</p></article></section><section class="section"><div class="section-head"><div><p class="eyebrow">PROJECT GALLERY</p><h2>Project images</h2></div>${user.role!=='Client'?'<button class="secondary" data-action="gallery">Add images</button>':''}</div><div class="gallery"><img src="${banner}" alt="Project cover">${gallery.map(src=>`<img src="${src}" alt="Project gallery image">`).join('')}</div><p class="muted gallery-note">${gallery.length}/5 additional project images added.</p></section><section class="section"><div class="section-head"><div><p class="eyebrow">PURCHASE ORDERS</p><h2>Purchase order history</h2></div>${user.role!=='Client'?'<button class="primary" data-action="new-order">Generate new Purchase Order</button>':''}</div><div class="table project-orders">${rows}</div></section>`)}
function tools(){let cards=user.role==='Admin'?[['users','User management','Manage users, roles, and account status.'],['suppliers','Supplier management','Maintain the supplier directory.'],['settings','System configuration','Access the future official platform guide.']]:[['suppliers','Supplier management','Manage suppliers for your projects.']];return shell(`<section class="hero"><div><p class="eyebrow">WORKSPACE</p><h1>Tools</h1></div><button class="back-link" data-route="home">← Back to dashboard</button></section><div class="tools">${cards.map(x=>`<article class="tool"><span class="tool-icon">${icon[x[0]]||icon.suppliers}</span><h3>${x[1]}</h3><p>${x[2]}</p><button class="secondary" data-route="${x[0]}">Open</button></article>`).join('')}</div>`)}
function toolPage(kind){let content=kind==='users'?`<section class="section"><h2>All users</h2><div class="table">${data.users.map(x=>`<article class="data-row"><div><strong>${e(x.name)}</strong><p>${e(x.username)} · ${e(x.role)}</p></div>${status(x.active?'Active':'Disabled')}</article>`).join('')}</div></section>`:kind==='suppliers'?`<section class="section"><h2>Supplier directory</h2><div class="table"><div class="empty">Supplier directory is ready for configuration.</div></div></section>`:`<section class="panel"><h3>System configuration</h3><p class="muted">The official platform guide PDF will be placed here when it is provided.</p></section>`;let title=kind==='users'?'User management':kind==='suppliers'?'Supplier management':'System configuration';return shell(`<section class="hero"><div><p class="eyebrow">TOOLS</p><h1>${title}</h1></div><button class="back-link" data-route="tools">← Back to tools</button></section>${content}`)}
function login(){return `<section class="login"><div class="login-side"><div class="login-copy"><h1>Clear progress for every project.</h1></div></div><div class="login-panel"><div class="login-card"><div class="login-logo">${logo()}</div><p class="eyebrow">WELCOME TO VAAK</p><h2>Sign in to your workspace</h2><form id="login"><div class="field"><label>Username</label><input name="username" required></div><div class="field"><label>Password</label><div class="password-wrap"><input id="password" name="password" type="password" required><button class="eye" type="button" data-action="eye">Show password</button></div></div><button class="primary wide">Sign in →</button></form></div></div></section>`}
function open(title,html,label,fn,opts={}){modal.innerHTML=`<div class="modal-backdrop"><form class="modal ${opts.className||''}" id="modal-form"><header class="modal-head"><h2>${title}</h2><button type="button" class="ghost" data-action="close">✕</button></header><div class="modal-body">${html}</div><footer class="modal-foot">${opts.footer||'<button type="button" class="secondary" data-action="close">Cancel</button>'}<button class="primary">${label}</button></footer></form></div>`;document.querySelector('#modal-form').onsubmit=ev=>{ev.preventDefault();fn(ev.currentTarget)}}
const field=(label,name,type='text',required=false)=>`<div class="field"><label>${label}</label><input name="${name}" type="${type}" ${required?'required':''}></div>`;const area=(label,name)=>`<div class="field"><label>${label}</label><textarea name="${name}" rows="2"></textarea></div>`;const section=(title,content)=>`<fieldset class="po-form-section"><legend>${title}</legend>${content}</fieldset>`;
function poForm(){let items=Array.from({length:11},(_,i)=>`<div class="po-item-form"><strong>Item ${i+1}</strong>${field('Side mark',`items[${i}][sideMark]`)}${area('Description',`items[${i}][description]`)}${field('Quantity',`items[${i}][qty]`,'number')}${field('Unit cost',`items[${i}][unitCost]`,'number')}${field('Extension',`items[${i}][extension]`,'number')}</div>`).join('');return `<div class="po-form-intro">Complete the fields from the HPG Purchase Order template.</div><div class="po-form-grid">${field('PO number','number','text',true)}${field('Project','project','text',true)}${field('Area','area')}${field('Project contact','projectContact')}${field('Manufacturer','manufacturer','text',true)}${field('Manufacturer contact','manufacturerContact')}${field('Source','source')}${field('Source contact','sourceContact')}${field('Ship to','shipTo')}${field('Final destination','finalDestination')}${field('Bill to','billTo')}${field('Shipping instructions','shippingInstructions')}${field('Delivery date','deliveryDate','date')}${field('Freight','freight')}${field('Terms','terms')}${field('Currency','currency')}${field('Specified by','specifiedBy')}${field('Side mark','sideMark')}${field('Prep by','prepBy')}${field('PO total','poTotal','number')}</div>${section('Items',`<div class="po-items-form">${items}</div>`)}${section('Totals & commercial terms',`<div class="po-form-grid">${area('Payment terms','paymentTerms')}${field('Incoterm','incoterm')}${field('Production time','productionTime')}${field('Warranty','warranty')}${area('Instructions','instructions')}${field('Subtotal','subtotal','number')}${field('Valor CIF','valorCif','number')}${field('PO total','commercialPoTotal','number')}</div>`)}${section('Approvals',`<div class="po-form-grid">${field('Approved by','approvedBy')}${field('Approval title','approvedByTitle')}${field('Approval signature','approvalSignature')}${field('Approval date','approvalDate','date')}${field('Vendor company name','vendorCompany')}${field('Vendor signature','vendorSignature')}${field('Vendor signature title','vendorSignatureTitle')}${field('Vendor date','vendorDate','date')}${field('Agent / entity','agentEntity')}${field('Agent signature','agentSignature')}${field('Agent date','agentDate','date')}${field('Approved for','approvedFor')}${field('Shipping date','shippingDate','date')}${field('Approved','approved')}</div>`)}${section('Terms and conditions',Array.from({length:12},(_,i)=>area(`${String(i+1).padStart(2,'0')}`,`conditions[${i}]`)).join(''))}`}
function formDataToOrder(form){let d=new FormData(form),o={id:'o'+Date.now(),projectId:p().id,issuer:user.name,visible:true,createdAt:new Date().toISOString(),items:[]};for(const [key,value] of d.entries()){let m=key.match(/^items\[(\d+)\]\[(\w+)\]$/);if(m){o.items[+m[1]]??={};o.items[+m[1]][m[2]]=value}else if(key.startsWith('conditions[')){o.conditions??=[];o.conditions[+key.match(/\d+/)[0]]=value}else o[key]=value}o.date=o.deliveryDate||new Date().toLocaleDateString('en-GB');o.supplier=o.supplier||o.manufacturer;return o}
function pv(o,k){return e(o?.[k]||'')}function previewOrder(o){let items=(o.items||[]).filter(x=>Object.values(x).some(Boolean)),rows=Array.from({length:11},(_,i)=>{let x=items[i]||{};return `<tr><td>${i+1}</td><td>${pv(x,'sideMark')}</td><td>${pv(x,'description')}</td><td>${pv(x,'qty')}</td><td>${pv(x,'unitCost')}</td><td>${pv(x,'extension')}</td></tr>`}).join('');let conditions=Array.from({length:12},(_,i)=>`<li><b>${String(i+1).padStart(2,'0')}</b><span>${e(o?.conditions?.[i]||'')}</span></li>`).join('');return `<div class="po-preview" id="order-preview"><div class="po-preview-head"><div class="hpg-mark">HPG<small>INTERNATIONAL</small></div><div><small>AS AGENT</small><h1>PURCHASE ORDER</h1></div></div><div class="po-meta"><div><b>PO NUMBER</b><span>${pv(o,'number')}</span></div><div><b>PROJECT</b><span>${pv(o,'project')}<br>Area: ${pv(o,'area')}</span></div><div><b>PROJECT CONTACT</b><span>${pv(o,'projectContact')}</span></div></div><h4>PARTIES</h4><div class="po-box-grid">${[['MANUFACTURER','manufacturer','manufacturerContact'],['SOURCE','source','sourceContact'],['SHIP TO','shipTo','finalDestination'],['BILL TO','billTo','']].map(x=>`<div><b>${x[0]}</b><span>${pv(o,x[1])}</span>${x[2]?`<small>${pv(o,x[2])}</small>`:''}</div>`).join('')}</div><h4>COMMERCIAL TERMS</h4><div class="po-commercial">${[['SHIPPING INSTRUCTIONS','shippingInstructions'],['DELIVERY DATE','deliveryDate'],['FREIGHT','freight'],['TERMS','terms'],['CURRENCY','currency'],['SPECIFIED BY','specifiedBy'],['SIDE MARK','sideMark'],['PREP BY','prepBy'],['PO TOTAL','poTotal']].map(x=>`<div><b>${x[0]}</b><span>${pv(o,x[1])}</span></div>`).join('')}</div><table class="po-items-table"><thead><tr><th>ITEM</th><th>SIDE MARK</th><th>DESCRIPTION</th><th>QTY</th><th>UNIT COST</th><th>EXTENSION</th></tr></thead><tbody>${rows}</tbody></table><div class="po-totals"><div><h4>TOTALS & COMMERCIAL TERMS</h4><p><b>PAYMENT TERMS</b> ${pv(o,'paymentTerms')}</p><p><b>INCOTERM</b> ${pv(o,'incoterm')}</p><p><b>PRODUCTION TIME</b> ${pv(o,'productionTime')} &nbsp; <b>WARRANTY</b> ${pv(o,'warranty')}</p><p><b>INSTRUCTIONS</b> ${pv(o,'instructions')}</p></div><div><p>Subtotal <strong>${pv(o,'subtotal')}</strong></p><p>Valor CIF <strong>${pv(o,'valorCif')}</strong></p><h3>PO TOTAL <strong>${pv(o,'commercialPoTotal')||pv(o,'poTotal')}</strong></h3></div></div><h4>APPROVALS</h4><div class="po-approvals">${[['APPROVED BY','approvedBy','approvedByTitle','approvalDate'],['ACCEPTED BY VENDOR','vendorCompany','vendorSignatureTitle','vendorDate'],['AGENT / ENTITY','agentEntity','agentSignature','agentDate'],['APPROVED FOR','approvedFor','shippingDate','approved']].map(x=>`<div><b>${x[0]}</b><span>${pv(o,x[1])}</span><small>${pv(o,x[2])} · ${pv(o,x[3])}</small></div>`).join('')}</div><h2>TERMS AND CONDITIONS</h2><ol class="po-conditions">${conditions}</ol><footer>HPG International Latinoamericana SAC · RUC 20600893123 · hpgilatam.com</footer></div>`}
function showPoForm(){open('Nueva orden de compra',poForm(),'Continuar',form=>{draftOrder=formDataToOrder(form);open('Previsualización de orden de compra',previewOrder(draftOrder),'Generar orden de compra',()=>{data.orders.push(draftOrder);save();modal.innerHTML='';msg('Orden de compra generada y guardada en el historial.');render()},{className:'po-preview-modal',footer:'<button type="button" class="secondary" data-action="po-back">← Volver al formulario</button>'})},{className:'po-form-modal'})}
function printOrder(o){let w=window.open('','_blank','noopener');if(!w)return msg('Permite ventanas emergentes para imprimir la orden.');let body=previewOrder(o).replace('src="assets/hpg-international-logo.png"',`src="${new URL('assets/hpg-international-logo.png',location.href).href}"`);w.document.write(`<html><head><title>${e(o.number||'Purchase Order')}</title><link rel="stylesheet" href="${new URL('styles.css',location.href).href}"><link rel="stylesheet" href="${new URL('refinements.css',location.href).href}"></head><body class="print-order">${body}<script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
function confirmDelete(id){let o=data.orders.find(x=>x.id===id);open('Eliminar orden de compra','<p class="delete-confirm">ESTÁS SEGURO DE QUE DESEAS ELIMINAR ESTA ORDEN DE COMPRA?</p><p class="muted">'+e(o?.number||'')+'</p>','Sí, eliminar',()=>{data.orders=data.orders.filter(x=>x.id!==id);save();modal.innerHTML='';msg('La orden de compra fue eliminada.');render()},{footer:'<button type="button" class="secondary" data-action="close">No, volver</button>',className:'delete-modal'})}
function action(a,id){if(a==='logout'){localStorage.removeItem(SESSION);user=null;return render()}if(a==='close'){modal.innerHTML='';return}if(a==='po-back')return showPoForm();if(a==='eye'){let x=document.querySelector('#password');x.type=x.type==='password'?'text':'password';return}if(a==='new-order')return showPoForm();if(a==='preview-order')return open('Previsualización de orden de compra',previewOrder(data.orders.find(x=>x.id===id)),'Cerrar',()=>{modal.innerHTML=''},{className:'po-preview-modal'});if(a==='download-order')return printOrder(data.orders.find(x=>x.id===id));if(a==='delete-order')return confirmDelete(id);if(a==='task'){let x=data.tasks.find(x=>x.id===id);x.status=x.status==='Pending'?'In Progress':x.status==='In Progress'?'Completed':'Pending';save();return render()}if(a==='new-task'||a==='edit-task'){let x=a==='edit-task'?data.tasks.find(t=>t.id===id):null;return open(a==='edit-task'?'Edit objective':'Add objective',`${field('Objective','title','text',true)}${field('Due date','due','text',true)}${field('Assignee username','assignee','text',true)}`,'Save',f=>{let d=new FormData(f),person=data.users.find(u=>u.username===d.get('assignee'));if(!person)return msg('Enter an existing username.');if(x)Object.assign(x,{title:d.get('title'),due:d.get('due'),assignee:person.id});else data.tasks.push({id:'t'+Date.now(),title:d.get('title'),due:d.get('due'),created:new Date().toLocaleDateString('en-GB'),assignee:person.id,status:'Pending'});save();modal.innerHTML='';render()})}if(a==='gallery')return open('Add project images','<div class="field"><label>Project images (maximum 5)</label><input name="images" type="file" accept="image/*" multiple></div>','Add images',f=>{let files=[...f.images.files].slice(0,5-(p().gallery||[]).length);Promise.all(files.map(file=>new Promise(ok=>{let r=new FileReader();r.onload=()=>ok(r.result);r.readAsDataURL(file)}))).then(img=>{p().gallery.push(...img);save();modal.innerHTML='';render()})})}
function render(){app.innerHTML=!user?login():['users','suppliers','settings'].includes(route)?toolPage(route):route==='project'?details():route==='tools'?tools():home()}
data.projects.forEach(x=>{if(!Array.isArray(x.warehouses))x.warehouses=[x.warehouse||'Project warehouse'];if(!x.warehouse)x.warehouse=x.warehouses[0]});save();
const moneyField=(label,name)=>`<div class="field money-field"><label>${label}</label><div class="money-input"><input name="${name}" type="number" step="0.01"><select name="${name}Currency" aria-label="${label} currency"><option value="USD">USD ($)</option><option value="PEN">PEN (S/)</option></select></div></div>`;
const warehouseField=()=>`<div class="field warehouse-field"><label>Warehouse address</label><div class="warehouse-input"><select name="warehouseAddress">${(p().warehouses||[]).map(x=>`<option value="${e(x)}">${e(x)}</option>`).join('')}</select><button type="button" class="secondary" data-action="add-warehouse">Add new address</button></div></div>`;
const itemForm=i=>`<div class="po-item-form" data-item="${i}"><strong>Item ${i+1}</strong>${field('Side mark',`items[${i}][sideMark]`)}${area('Description',`items[${i}][description]`)}${field('Quantity',`items[${i}][qty]`,'number')}${moneyField('Unit cost',`items[${i}][unitCost]`)}${moneyField('Extension',`items[${i}][extension]`)}<button type="button" class="danger item-remove" data-action="remove-item" data-id="${i}">Remove item</button></div>`;
poForm=()=>`<div class="po-form-intro">Complete the fields from the HPG Purchase Order template.</div><div class="po-form-grid">${field('PO number','number','text',true)}${field('Project','project','text',true)}${field('Area','area')}${field('Project contact','projectContact')}${field('Manufacturer','manufacturer','text',true)}${field('Manufacturer contact','manufacturerContact')}${field('Source','source')}${field('Source contact','sourceContact')}${field('Ship to','shipTo')}${field('Final destination','finalDestination')}${field('Bill to','billTo')}${warehouseField()}${field('Shipping instructions','shippingInstructions')}${field('Delivery date','deliveryDate','date')}${field('Freight','freight')}${field('Terms','terms')}${field('Currency','currency')}${field('Specified by','specifiedBy')}${field('Side mark','sideMark')}${field('Prep by','prepBy')}${moneyField('PO total','poTotal')}</div>${section('Items',`<div class="po-items-form">${itemForm(0)}</div><button type="button" class="secondary add-item" data-action="add-item">Add item</button>`)}${section('Totals & commercial terms',`<div class="po-form-grid">${area('Payment terms','paymentTerms')}${field('Incoterm','incoterm')}${field('Production time','productionTime')}${field('Warranty','warranty')}${area('Instructions','instructions')}${moneyField('Subtotal','subtotal')}${moneyField('Valor CIF','valorCif')}${moneyField('PO total','commercialPoTotal')}</div>`)}${section('Approvals',`<div class="po-form-grid">${field('Approved by','approvedBy')}${field('Approval title','approvedByTitle')}${field('Approval signature','approvalSignature')}${field('Approval date','approvalDate','date')}${field('Vendor company name','vendorCompany')}${field('Vendor signature','vendorSignature')}${field('Vendor signature title','vendorSignatureTitle')}${field('Vendor date','vendorDate','date')}${field('Agent / entity','agentEntity')}${field('Agent signature','agentSignature')}${field('Agent date','agentDate','date')}${field('Approved for','approvedFor')}${field('Shipping date','shippingDate','date')}${field('Approved','approved')}</div>`)}${section('Terms and conditions',Array.from({length:12},(_,i)=>area(`${String(i+1).padStart(2,'0')}`,`conditions[${i}]`)).join(''))}`;
const oldToolPage=toolPage;toolPage=kind=>{if(kind==='settings'){let active=localStorage.getItem('vaak-language-'+(localStorage.getItem(SESSION)||'guest'))||'es';return shell(`<section class="hero"><div><p class="eyebrow">TOOLS</p><h1>System configuration</h1></div><button class="back-link" data-route="tools">← Back to tools</button></section><section class="panel"><h3>Platform language</h3><p class="muted">This preference affects only your own view.</p><div class="field"><label for="user-language">Language</label><select id="user-language"><option value="es" ${active==='es'?'selected':''}>Español</option><option value="en" ${active==='en'?'selected':''}>English</option></select></div></section>`)}if(kind!=='users')return oldToolPage(kind);return shell(`<section class="hero"><div><p class="eyebrow">TOOLS</p><h1>User management</h1></div><button class="back-link" data-route="tools">← Back to tools</button></section><section class="section"><h2>All users</h2><div class="table">${data.users.map(x=>`<article class="data-row user-row"><div><strong>${e(x.name)}</strong><p>${e(x.username)} · ${e(x.role)}</p></div><div class="user-actions">${status(x.active?'Active':'Disabled')}<button class="secondary" data-action="edit-user" data-id="${x.id}">Edit data</button>${x.id===user.id?'':`<button class="${x.active?'danger':'secondary'}" data-action="toggle-user" data-id="${x.id}">${x.active?'Disable user':'Enable user'}</button>`}</div></article>`).join('')}</div></section>`)};
const oldPreviewOrder=previewOrder;previewOrder=o=>{let base=oldPreviewOrder(o),rows=(o.items||[]).filter(x=>Object.values(x).some(Boolean));base=base.replace(/<tbody>.*?<\/tbody>/,`<tbody>${rows.map((x,i)=>`<tr><td>${i+1}</td><td>${pv(x,'sideMark')}</td><td>${pv(x,'description')}</td><td>${pv(x,'qty')}</td><td>${pv(x,'unitCost')} ${pv(x,'unitCostCurrency')}</td><td>${pv(x,'extension')} ${pv(x,'extensionCurrency')}</td></tr>`).join('')}</tbody>`);return base.replace('class="hpg-mark">HPG<small>INTERNATIONAL</small>','class="hpg-mark"><img class="po-logo" src="assets/hpg-international-logo.png" alt="HPG International logo">')};
const baseAction=action;action=(a,id)=>{if(a==='add-item'){let box=document.querySelector('.po-items-form'),i=box.querySelectorAll('.po-item-form').length;box.insertAdjacentHTML('beforeend',itemForm(i));return}if(a==='remove-item'){let item=document.querySelector(`[data-item="${id||''}"]`)||document.querySelector('.item-remove')?.closest('.po-item-form');if(item&&document.querySelectorAll('.po-item-form').length>1)item.remove();return}if(a==='add-warehouse')return open('Add warehouse address',field('Warehouse address','warehouse','text',true),'Save address',f=>{let d=new FormData(f),address=d.get('warehouse');if(address){p().warehouses??=[];p().warehouses.push(address);p().warehouse=address;save();modal.innerHTML='';showPoForm()}});if(a==='edit-user'){let x=data.users.find(u=>u.id===id);return open('Edit user',`<div class="form-grid"><div class="field"><label>Name</label><input name="name" value="${e(x.name)}" required></div><div class="field"><label>Username</label><input name="username" value="${e(x.username)}" required></div><div class="field"><label>Role</label><select name="role"><option ${x.role==='Admin'?'selected':''}>Admin</option><option ${x.role==='Worker'?'selected':''}>Worker</option><option ${x.role==='Client'?'selected':''}>Client</option></select></div></div>`,'Save changes',f=>{let d=new FormData(f);Object.assign(x,{name:d.get('name'),username:d.get('username'),role:d.get('role')});save();modal.innerHTML='';render();msg('User data updated.')})}if(a==='toggle-user'){let x=data.users.find(u=>u.id===id);if(x){x.active=!x.active;save();render();msg('User status updated.')}return}return baseAction(a,id)};
document.addEventListener('click',ev=>{let t=ev.target.closest('[data-route],[data-action],[data-project]');if(!t)return;if(t.dataset.route){route=t.dataset.route;return render()}if(t.dataset.project){selected=t.dataset.project;route='project';return render()}action(t.dataset.action,t.dataset.id)});document.addEventListener('keydown',ev=>{if((ev.key==='Enter'||ev.key===' ')&&ev.target.dataset.project){selected=ev.target.dataset.project;route='project';render()}});document.addEventListener('submit',ev=>{if(ev.target.id==='login'){ev.preventDefault();let d=new FormData(ev.target),x=data.users.find(x=>x.username===d.get('username')&&x.password===d.get('password')&&x.active);if(!x)return msg('Invalid username or password.');user=x;localStorage.setItem(SESSION,x.id);render()}});render();

