const money=(label,name)=>`<div class="field money-field"><label>${label}</label><div class="money-input"><input name="${name}" type="number" step="0.01"><select name="${name}Currency" aria-label="${label} currency"><option value="USD">USD ($)</option><option value="PEN">PEN (S/)</option></select><output class="money-display" data-money-for="${name}"></output></div></div>`;
const fieldValue=(label,name,type='text',required=false,value='')=>`<div class="field"><label>${label}</label><input name="${name}" type="${type}" value="${e(value)}" ${required?'required':''}></div>`;
const orderItem=i=>`<div class="po-item-form" data-item="${i}"><strong>Item ${i+1}</strong>${field('Side mark',`items[${i}][sideMark]`)}${area('Description',`items[${i}][description]`)}${field('Quantity',`items[${i}][qty]`,'number')}${money('Unit cost',`items[${i}][unitCost]`)}${money('Extension',`items[${i}][extension]`)}<button type="button" class="danger item-remove" data-action="remove-item" data-id="${i}">Remove item</button></div>`;
poForm=()=>{let count=Math.max(1,draftOrder?.items?.length||1);return `<div class="po-form-intro">Complete the fields from the HPG Purchase Order template.</div><div class="po-form-grid">${field('Project','project','text',true)}${field('Area','area')}${field('Project contact','projectContact')}${field('Manufacturer','manufacturer','text',true)}${field('Manufacturer contact','manufacturerContact')}${field('Source','source')}${field('Source contact','sourceContact')}${field('Ship to','shipTo')}${field('Final destination','finalDestination')}${field('Bill to','billTo')}${warehouseField()}${field('Shipping instructions','shippingInstructions')}${field('Delivery date','deliveryDate','date')}${field('Freight','freight')}${field('Terms','terms')}${field('Currency','currency')}${field('Specified by','specifiedBy')}${field('Side mark','sideMark')}${field('Prep by','prepBy')}${money('PO total','poTotal')}</div>${section('Items',`<div class="po-items-form">${Array.from({length:count},(_,i)=>orderItem(i)).join('')}</div><button type="button" class="secondary add-item" data-action="add-item">Add item</button>`)}${section('Totals & commercial terms',`<div class="po-form-grid">${area('Payment terms','paymentTerms')}${field('Incoterm','incoterm')}${field('Production time','productionTime')}${field('Warranty','warranty')}${area('Instructions','instructions')}${money('Subtotal','subtotal')}${money('Valor CIF','valorCif')}${money('PO total','commercialPoTotal')}</div>`)}${section('Approvals',`<div class="po-form-grid">${field('Approved by','approvedBy')}${field('Approval title','approvedByTitle')}${field('Approval signature','approvalSignature')}${field('Approval date','approvalDate','date')}${field('Vendor company name','vendorCompany')}${field('Vendor signature','vendorSignature')}${field('Vendor signature title','vendorSignatureTitle')}${field('Vendor date','vendorDate','date')}${field('Agent / entity','agentEntity')}${field('Agent signature','agentSignature')}${field('Agent date','agentDate','date')}${field('Approved for','approvedFor')}${field('Shipping date','shippingDate','date')}${field('Approved','approved')}</div>`)}${section('Terms and conditions',Array.from({length:12},(_,i)=>area(`${String(i+1).padStart(2,'0')}`,`conditions[${i}]`)).join(''))}`};
const orderNumber=()=>String(data.orders.reduce((max,o)=>Math.max(max,Number(String(o.number||'').match(/\d+$/)?.[0]||0)),0)+1).padStart(5,'0');
function fillOrderForm(o){if(!o)return;Object.entries(o).forEach(([key,value])=>{if(['items','conditions','id','projectId','issuer','visible','createdAt','date','supplier'].includes(key))return;let input=document.querySelector(`#modal-form [name="${key}"]`);if(input){input.value=value??'';input.dispatchEvent(new Event('input',{bubbles:true}))}});(o.conditions||[]).forEach((v,i)=>{let x=document.querySelector(`#modal-form [name="conditions[${i}]"]`);if(x)x.value=v||''});(o.items||[]).forEach((item,i)=>Object.entries(item).forEach(([key,value])=>{let x=document.querySelector(`#modal-form [name="items[${i}][${key}]"]`);if(x){x.value=value??'';x.dispatchEvent(new Event('input',{bubbles:true}))}}));updateMoneyDisplays()}
function updateMoneyDisplays(){document.querySelectorAll('.money-display').forEach(out=>{let input=document.querySelector(`[name="${out.dataset.moneyFor}"]`),currency=document.querySelector(`[name="${out.dataset.moneyFor}Currency"]`),value=Number(input?.value);out.textContent=input?.value!==''&&!Number.isNaN(value)?`${currency?.value==='PEN'?'S/':'$'} ${value.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}`:''})}
showPoForm=()=>{open('New purchase order',poForm(),'Continue',form=>{draftOrder=formDataToOrder(form);draftOrder.number=draftOrder.number||orderNumber();open('Purchase Order preview',previewOrder(draftOrder),'Generate purchase order',()=>{data.orders.push(draftOrder);save();draftOrder=null;modal.innerHTML='';msg('Purchase order generated and saved.');render()},{className:'po-preview-modal',footer:'<button type="button" class="secondary" data-action="po-back">← Back to form</button>'})},{className:'po-form-modal'});fillOrderForm(draftOrder)};
const oldTools=tools;tools=()=>{let html=oldTools();return html.replace('</div></main>','<article class="tool"><span class="tool-icon">▤</span><h3>Purchase order history</h3><p>Review every purchase order generated across all projects.</p><button class="secondary" data-route="orders">Open</button></article></div></main>')};
const oldToolPage2=toolPage;toolPage=kind=>{if(kind!=='orders')return oldToolPage2(kind);let rows=data.orders.map(o=>{let project=data.projects.find(x=>x.id===o.projectId);return `<article class="data-row"><div><strong>${e(o.number)}</strong><p>${e(project?.name||'')} · ${e(o.supplier||o.manufacturer||'')} · ${e(o.date||o.deliveryDate||'')}</p></div><button class="order-icon" data-action="preview-order" data-id="${o.id}">◉</button></article>`}).join('')||'<div class="empty">No purchase orders yet.</div>';return shell(`<section class="hero"><div><p class="eyebrow">TOOLS</p><h1>Purchase order history</h1></div><button class="back-link" data-route="tools">← Back to tools</button></section><section class="panel history-filters"><div class="po-form-grid"><div class="field"><label>Project</label><select id="history-project"><option value="">All projects</option>${data.projects.map(x=>`<option value="${x.id}">${e(x.name)}</option>`).join('')}</select></div><div class="field"><label>Issue date</label><input id="history-date" type="date"></div></div></section><section class="section"><div class="table" id="global-order-history">${rows}</div></section>`)};
const oldDetails2=details;details=()=>{let html=oldDetails2(),x=p(),team=x.team||[],teamHtml=team.map(function(m,i){return '<div class="team-member"><p><strong>'+e(m.name)+'</strong><br>'+e(m.contact)+' · '+e(m.role)+'</p><button class="danger" data-action="remove-team-member" data-id="'+i+'">Remove</button></div>'}).join('')||'<p class="muted">No client team members added.</p>';html=html.replace('<h3>General information</h3>','<div class="card-title-row"><h3>General information</h3><button class="secondary" data-action="edit-project-card" data-card="general">Edit data</button></div>').replace('<h3>Project areas</h3>','<div class="card-title-row"><h3>Project areas</h3><button class="secondary" data-action="edit-project-card" data-card="areas">Edit data</button></div>').replace('<h3>Client team</h3><p>Project Client Contact<br>Project coordination<br>contact@example.test</p>','<div class="card-title-row"><h3>Client team</h3><button class="secondary" data-action="add-team-member">Add member</button></div>'+teamHtml);html=html.replace(/<img src="([^"]+)" alt="Project cover">/,'<img class="gallery-image" data-action="view-image" data-id="$1" data-src="$1" src="$1" alt="Project cover">').replace(/<img src="([^"]+)" alt="Project gallery image">/g,function(m,src){return '<img class="gallery-image" data-action="view-image" data-id="'+src+'" data-src="'+src+'" src="'+src+'" alt="Project gallery image">'});return html};
const oldRender2=render;render=()=>{if(user&&route==='orders'){app.innerHTML=toolPage('orders');return}oldRender2()};
const oldAction2=action;action=(a,id)=>{if(a==='po-back'){return showPoForm()};if(a==='add-item'){let box=document.querySelector('.po-items-form'),i=box.querySelectorAll('.po-item-form').length;box.insertAdjacentHTML('beforeend',orderItem(i));return}if(a==='remove-item'){let item=document.querySelector(`[data-item="${id}"]`);if(item&&document.querySelectorAll('.po-item-form').length>1)item.remove();return}if(a==='add-warehouse')return open('Add warehouse address',field('Warehouse address','warehouse','text',true),'Save address',f=>{let d=new FormData(f),address=d.get('warehouse');if(address){p().warehouses.push(address);p().warehouse=address;save();modal.innerHTML='';showPoForm()}});if(a==='edit-project-card'){let x=p(),card=id==='general'?['Legal business name','legal',x.legal,'Tax ID','tax',x.tax,'Fiscal address','fiscal',x.fiscal,'Delivery / warehouse','warehouse',x.warehouse]:['Guest rooms','rooms',x.rooms,'Residences','residences',x.residences,'Common areas','areas',x.areas];return open('Edit project data',card.filter((_,i)=>i%3===0).map((label,i)=>fieldValue(label,card[i*3+1],'text',false,card[i*3+2])).join(''),'Save changes',f=>{let d=new FormData(f);card.filter((_,i)=>i%3===1).forEach(key=>{x[key]=d.get(key)});save();modal.innerHTML='';render()})}if(a==='add-team-member')return open('Add client team member',`${field('Name and surname','name','text',true)}${field('Contact number','contact','text',true)}${field('Position','role','text',true)}`,'Save member',f=>{let d=new FormData(f);p().team.push({name:d.get('name'),contact:d.get('contact'),role:d.get('role')});save();modal.innerHTML='';render()});if(a==='remove-team-member'){p().team.splice(Number(id),1);save();return render()}if(a==='view-image'){let src=document.querySelector(`[data-src="${id||''}"]`)?.src||document.querySelector('.gallery-image')?.src;return open('Project image',`<div class="image-viewer"><img src="${src}" alt="Project image"><button type="button" class="danger" data-action="delete-viewed-image" data-src="${src}">Delete image</button></div>`,'Close',()=>{modal.innerHTML=''},{className:'image-modal'})}if(a==='delete-viewed-image'){let src=document.querySelector('[data-action="delete-viewed-image"]')?.dataset.src;if(src&&p().gallery?.includes(src)){p().gallery=p().gallery.filter(x=>x!==src);save();modal.innerHTML='';render()}return}return oldAction2(a,id)};
document.addEventListener('input',ev=>{if(ev.target.matches('.money-field input'))updateMoneyDisplays();if(ev.target.id==='history-project'||ev.target.id==='history-date')filterHistory()});document.addEventListener('change',ev=>{if(ev.target.matches('.money-field select'))updateMoneyDisplays();if(ev.target.id==='history-project'||ev.target.id==='history-date')filterHistory()});
function filterHistory(){let project=document.querySelector('#history-project')?.value,date=document.querySelector('#history-date')?.value,box=document.querySelector('#global-order-history');if(!box)return;let rows=data.orders.filter(o=>(!project||o.projectId===project)&&(!date||(o.date||o.deliveryDate||'').startsWith(date))).map(o=>`<article class="data-row"><div><strong>${e(o.number)}</strong><p>${e(data.projects.find(x=>x.id===o.projectId)?.name||'')} · ${e(o.supplier||o.manufacturer||'')} · ${e(o.date||o.deliveryDate||'')}</p></div><button class="order-icon" data-action="preview-order" data-id="${o.id}">◉</button></article>`).join('')||'<div class="empty">No purchase orders match the filters.</div>';box.innerHTML=rows}

