const specValue=(x,k)=>e(x?.[k]||''),specInput=(label,name,value='')=>fieldValue(label,name,'text',false,value);
function specForm(){return `<div class="po-form-grid">${specInput('Item code','itemCode')}${specInput('Project','project')}${specInput('Project number','projectNumber')}${specInput('Client','client')}${specInput('Area','area')}${specInput('Category','category')}${specInput('Vendor / source','vendor')}${specInput('Source','source')}${specInput('Issue date','issueDate','')}${specInput('Status','status')}${specInput('Model / description','model')}${specInput('Reference number','reference')}${specInput('Size as ordered','size')}${specInput('Finish / color','finish')}${specInput('Quantity ordered','qty')}${specInput('Description','description')}${specInput('Design & finish','design')}${specInput('Construction & craftsmanship','construction')}${specInput('Project notes','notes')}${specInput('By','by')}${specInput('Item','item')}${specInput('Item number','itemNumber')}${money('Cost','cost')}${specInput('Image caption','imageCaption')}<div class="field spec-image-field"><label>Spec image from local gallery</label><input name="image" type="file" accept="image/*"></div></div>`}
function specPreview(x){return `<div class="spec-preview"><div class="spec-preview-head"><div class="hpg-mark"><img class="po-logo" src="assets/hpg-international-logo.png" alt="HPG International logo"></div><div><div class="spec-code">ITEM CODE<span>${specValue(x,'itemCode')}</span></div><h1>TECHNICAL SPECIFICATION SHEET</h1><small>HPG International - FF&E Procurement</small></div></div><table class="spec-data-table"><tr><th>PROJECT</th><td>${specValue(x,'project')}</td><th>CATEGORY</th><td>${specValue(x,'category')}</td></tr><tr><th>PROJECT #</th><td>${specValue(x,'projectNumber')}</td><th>VENDOR / SOURCE</th><td>${specValue(x,'vendor')} / ${specValue(x,'source')}</td></tr><tr><th>CLIENT</th><td>${specValue(x,'client')}</td><th>ISSUE DATE</th><td>${specValue(x,'issueDate')}</td></tr><tr><th>AREA</th><td>${specValue(x,'area')}</td><th>STATUS</th><td>${specValue(x,'status')}</td></tr></table><h4>SPECIFICATION</h4><table class="spec-item-table"><tr><th>MODEL / DESCRIPTION</th><td>${specValue(x,'model')}</td></tr><tr><th>REFERENCE #</th><td>${specValue(x,'reference')}</td></tr><tr><th>SIZE (AS ORDERED)</th><td>${specValue(x,'size')}</td></tr><tr><th>FINISH / COLOR</th><td>${specValue(x,'finish')}</td></tr><tr><th>QTY. ORDERED</th><td>${specValue(x,'qty')}</td></tr></table>${x.image?`<img class="spec-image" src="${e(x.image)}" alt="${specValue(x,'model')}">`:''}<h4>DESCRIPTION</h4><p>${specValue(x,'description')}</p><h4>DESIGN & FINISH</h4><p>${specValue(x,'design')}</p><h4>CONSTRUCTION & CRAFTSMANSHIP</h4><p>${specValue(x,'construction')}</p><h4>PROJECT NOTES</h4><p>${specValue(x,'notes')}</p><table class="spec-item-table"><tr><th>BY</th><th>QTY.</th><th>ITEM</th><th>ITEM #</th><th>COST</th></tr><tr><td>${specValue(x,'by')}</td><td>${specValue(x,'qty')}</td><td>${specValue(x,'item')}</td><td>${specValue(x,'itemNumber')}</td><td>${moneyText(x.cost,x.currency)}</td></tr></table><footer>HPG International Latinoamericana SAC · hpgilatam.com</footer></div>`}
const toolsWithHistory=tools;tools=()=>toolsWithHistory().replace('</div></main>','<article class="tool"><span class="tool-icon">▦</span><h3>Specs library</h3><p>Keep products and technical specification sheets in one place.</p><button class="secondary" data-route="specs">Open</button></article></div></main>');
const pageWithHistory=toolPage;toolPage=kind=>{if(kind!=='orders')return pageWithHistory(kind);let rows=data.orders.map(o=>`<article class="data-row"><div><strong>${e(o.number)}</strong><p>${e(data.projects.find(x=>x.id===o.projectId)?.name||'')} · ${e(o.supplier||o.manufacturer||'')} · ${e(o.date||o.deliveryDate||'')} · Generated by: ${e(o.issuerUsername||o.issuer||'')}</p></div><div class="order-actions"><button class="order-icon" data-action="preview-order" data-id="${o.id}">◉</button>${user.role!=='Client'?`<button class="order-icon delete-order" data-action="delete-order" data-id="${o.id}" title="Delete purchase order">⌫</button>`:''}</div></article>`).join('')||'<div class="empty">No purchase orders yet.</div>';return shell(`<section class="hero"><div><p class="eyebrow">TOOLS</p><h1>Purchase order history</h1></div><button class="back-link" data-route="tools">← Back to tools</button></section><section class="panel history-filters"><div class="po-form-grid"><div class="field"><label>Project</label><select id="history-project"><option value="">All projects</option>${data.projects.map(x=>`<option value="${x.id}">${e(x.name)}</option>`).join('')}</select></div><div class="field"><label>Issue date</label><input id="history-date" type="date"></div></div></section><section class="section"><div class="table" id="global-order-history">${rows}</div></section>`)};
const pageWithSpecs=toolPage;toolPage=kind=>{if(kind!=='specs')return pageWithSpecs(kind);return shell(`<section class="hero"><div><p class="eyebrow">TOOLS</p><h1>Specs library</h1><p>Saved products and their technical specification sheets.</p></div><button class="back-link" data-route="tools">← Back to tools</button></section><section class="section"><div class="section-head"><h2>Saved specs</h2><button class="primary" data-action="new-spec">Add new spec</button></div><div class="spec-library">${data.specs.map(x=>`<article class="spec-card"><img src="${e(x.image||'')}" alt="${specValue(x,'model')}"><div class="spec-card-body"><p class="eyebrow">${specValue(x,'itemCode')}</p><h3>${specValue(x,'model')}</h3><p>${specValue(x,'category')} · ${moneyText(x.cost,x.currency)}</p><div class="spec-card-actions"><button class="secondary" data-action="preview-spec" data-id="${x.id}">View technical sheet</button></div></div></article>`).join('')}</div></section>`)};
const renderWithSpecs=render;render=()=>{if(user&&['orders','specs'].includes(route)){app.innerHTML=toolPage(route);return}renderWithSpecs()};
const actionWithSpecs=action;action=(a,id)=>{if(a==='new-spec')return open('Add new spec',specForm(),'Save spec',form=>{let d=new FormData(form),spec={id:'s'+Date.now()};for(const [k,v] of d.entries())if(k!=='image'&&k!=='costCurrency')spec[k]=v;spec.cost=d.get('cost');spec.currency=d.get('costCurrency')||'USD';let file=form.image.files[0],done=image=>{spec.image=image||'assets/projects/harbor-view-residence.png';data.specs.push(spec);save();modal.innerHTML='';render();msg('Spec saved.')};if(file){let r=new FileReader();r.onload=()=>done(r.result);r.readAsDataURL(file)}else done('')},{className:'spec-form-modal'});if(a==='preview-spec')return open('Technical specification sheet',specPreview(data.specs.find(x=>x.id===id)),'Close',()=>{modal.innerHTML=''},{className:'spec-preview-modal'});if(a==='delete-order'){let o=data.orders.find(x=>x.id===id);return open('Delete purchase order',`<p class="delete-confirm">ARE YOU SURE YOU WANT TO DELETE THIS PURCHASE ORDER PERMANENTLY?</p><p class="muted">${e(o?.number||'')}</p>`,'Yes, delete',()=>{data.orders=data.orders.filter(x=>x.id!==id);save();modal.innerHTML='';render();msg('Purchase order deleted.')},{footer:'<button type="button" class="secondary" data-action="close">No, go back</button>'})}if(a==='new-order'){return actionWithSpecs(a,id)}let result=actionWithSpecs(a,id);if(a==='new-order'&&draftOrder)draftOrder.issuerUsername=user.username;return result};
const baseFormDataToOrder=formDataToOrder;formDataToOrder=form=>{let o=baseFormDataToOrder(form);o.issuerUsername=user.username;return o};
const moneyText=(value,currency)=>value!==''&&value!==undefined&&value!==null&&!Number.isNaN(Number(value))?`${currency==='PEN'?'S/':'$'} ${Number(value).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}`:'';
const previousPreview=previewOrder;previewOrder=o=>{let h=previousPreview(o),itemRows=(o.items||[]).filter(x=>Object.values(x).some(Boolean));h=h.replace(/(<b>PO TOTAL<\/b><span>)[^<]*/i,'$1'+moneyText(o.poTotal,o.poTotalCurrency));h=h.replace(/(Subtotal <strong>)[^<]*/i,'$1'+moneyText(o.subtotal,o.subtotalCurrency));h=h.replace(/(Valor CIF <strong>)[^<]*/i,'$1'+moneyText(o.valorCif,o.valorCifCurrency));h=h.replace(/(PO TOTAL <strong>)[^<]*/i,'$1'+moneyText(o.commercialPoTotal||o.poTotal,o.commercialPoTotal?o.commercialPoTotalCurrency:o.poTotalCurrency));itemRows.forEach((x,i)=>{let row=new RegExp(`(<tr><td>${i+1}<\/td><td>[^<]*<\/td><td>[^<]*<\/td><td>[^<]*<\/td><td>)[^<]*`);h=h.replace(row,'$1'+moneyText(x.unitCost,x.unitCostCurrency)).replace(new RegExp(`(<tr><td>${i+1}<\/td><td>[^<]*<\/td><td>[^<]*<\/td><td>[^<]*<\/td><td>[^<]*<\/td><td>)[^<]*`),'$1'+moneyText(x.extension,x.extensionCurrency))});return h};
